(() => {
  // packages/djaker-hakim/linkion-router/src/js/router/core-router.js
  var coreRouterTrait = {
    origin: "",
    pathname: "",
    hash: "",
    search: "",
    queryParams: {},
    href: "",
    readBaseUrl() {
      const loc = window.location;
      this.origin = loc.origin;
      this.pathname = loc.pathname;
      this.hash = loc.hash;
      this.search = loc.search;
      this.href = loc.href;
      this.queryParams = Object.fromEntries(new URLSearchParams(this.search).entries());
    }
  };

  // packages/djaker-hakim/linkion-router/src/js/router/route-parser.js
  var routeParser = {
    component: null,
    params: {},
    allParams: {},
    route: {},
    readUrl() {
      this.readBaseUrl();
      this.route = this.checkRoutes();
      if (this.route) {
        this.params = this.getParamsFromRoute(this.route.path, this.pathname);
        this.allParams = {
          ...this.params,
          ...this.queryParams
        };
      }
    },
    checkRoutes() {
      for (route of this.component.routes) {
        if (this.matchRoute(route)) return route;
      }
      return null;
    },
    matchRoute(route2) {
      if (!route2.path) return null;
      if (route2.path == this.pathname) return route2;
      if (this.getParamsFromRoute(route2.path, this.pathname)) return route2;
      return null;
    },
    getParamsFromRoute(pattern, path) {
      const paramNames = [];
      const regexPattern = pattern.replace(/\//g, "\\/").replace(/:(\w+)/g, (_, paramName) => {
        paramNames.push(paramName);
        return "([^/]+)";
      });
      const regex = new RegExp(`^${regexPattern}$`);
      const match = path.match(regex);
      if (!match) return null;
      const params2 = {};
      paramNames.forEach((name, index) => {
        params2[name] = match[index + 1];
      });
      return params2;
    },
    getRouteByName(name) {
      let [route2] = this.component.routes.filter((r) => {
        return r.name == name;
      });
      return route2;
    }
  };

  // packages/djaker-hakim/linkion-router/src/js/router/navigation.js
  var navigationTrait = {
    selector: "",
    getEl() {
      const el = document.createElement("div");
      document.querySelector(this.selector).replaceChildren(el);
      return el;
    },
    // TODO in navigation file
    // replace(path, params){},     
    to(pathOrName, allParams, hash) {
      this.setHref(this.buildUrl(pathOrName, allParams, hash));
    },
    redirectTo(pathOrName, allParams = {}, hash = "") {
      this.redirect(this.buildUrl(pathOrName, allParams, hash));
    },
    buildUrl(pathOrName, allParams = {}, hash = "") {
      let pathname = pathOrName;
      const { params: params2, queryParams } = allParams;
      route = this.getRouteByName(pathOrName);
      if (route) {
        pathname = route.path;
        if (params2) pathname = this.setParams(route.path, params2);
      }
      const url = new URL(location);
      url.pathname = pathname;
      url.search = this.setSearchParams(queryParams);
      url.hash = hash;
      return url;
    },
    forward() {
      history.forward();
    },
    back() {
      history.back();
    },
    go(delta) {
      history.go(delta);
    },
    setParams(pattern, params2) {
      if (pattern.indexOf(":") == -1) return pattern;
      let path = pattern;
      for (let key of Object.keys(params2)) {
        path = path.replace(":" + key, params2[key]);
      }
      return path;
    },
    setSearchParams(queryParams) {
      const searchParams = new URLSearchParams();
      for (const key in queryParams) {
        searchParams.set(key, params[key]);
      }
      return searchParams.toString();
    },
    setHash(hash) {
      location.hash = hash;
    },
    redirect(link) {
      history.replaceState({}, "", link);
      this.reload();
    },
    setHref(link) {
      history.pushState({}, "", link);
      this.reload();
    }
  };

  // packages/djaker-hakim/linkion-router/src/js/router/route.js
  var Route = class {
    constructor(router) {
      this.origin = router.origin;
      this.pathname = router.pathname;
      this.search = router.search;
      this.hash = router.hash;
      this.href = router.href;
      this.params = router.params;
      this.queryParams = router.queryParams;
      this.allParams = router.allParams;
      this.route = router.route;
    }
  };

  // packages/djaker-hakim/linkion-router/src/js/router/route-loader.js
  var routeLoader = {
    start() {
      this.readUrl();
      this.preload();
      window.addEventListener("popstate", () => {
        this.pathname + this.search == location.pathname + location.search ? this.hash = location.hash : this.reload();
      });
      linkion.emit("linkion-router:ready");
    },
    reload() {
      const from = new Route(this);
      this.readUrl();
      const to = new Route(this);
      if (!this.runGuards("before-navigation", to, from)) {
        this.runGuards("cancel-navigation", to, from);
        return;
      }
      if (this.route) {
        linkion.render(
          this.route.component,
          {
            atts: this.route.atts,
            params: this.params,
            queryParams: this.queryParams
          },
          this.getEl()
        ).then(() => {
          this.runGuards("after-navigation", to, from);
        });
      } else {
        let component = "page-error";
        let atts = {
          code: 404,
          message: "NOT_FOUND"
        };
        const route2 = this.getRouteByName("404-page");
        if (route2) {
          component = route2.component;
          atts = route2.atts;
        }
        linkion.render(component, { atts }, this.getEl());
      }
    },
    preload() {
      let routes = [];
      this.component.routes.forEach((route2) => {
        route2.preload ? routes.push(route2) : "";
      });
      if (routes.length == 0 && this.component.routes.length < 5) routes = this.component.routes;
      for (let route2 of routes) {
        linkion.render(
          route2.component,
          {
            atts: route2.atts
          }
        );
      }
    }
  };

  // packages/djaker-hakim/linkion-router/src/js/router/guards.js
  var guards = {
    guards: {},
    addGuard(event, callback) {
      if (!this.guards[event]) this.guards[event] = /* @__PURE__ */ new Map();
      const id = crypto.randomUUID();
      this.guards[event].set(id, callback);
      return id;
    },
    // remove guard
    removeGuard(id) {
      for (const event of Object.keys(this.guards)) {
        if (this.guards[event].has(id)) {
          this.guards[event].delete(id);
          return true;
        }
      }
      return false;
    },
    runGuards(event, to, from) {
      for (const [id, guard] of this.guards[event] || []) {
        const result = this.executeGuard(guard, to, from);
        if (result !== true) return result;
      }
      return true;
    },
    // Execute single guard with next() callback
    executeGuard(guard, to, from) {
      if (false) return true;
      const next = (value = true) => {
        return value;
      };
      return guard(to, from, next);
    }
  };

  // packages/djaker-hakim/linkion-router/src/js/main.js
  var Router = class {
    static traits = [
      coreRouterTrait,
      routeParser,
      navigationTrait,
      routeLoader,
      guards
    ];
    static register(...traits) {
      this.constructor.traits.push(...traits);
    }
    // linkion Router class builder
    constructor(lnkn, selector) {
      Object.assign(this, ...this.constructor.traits);
      this.component = lnkn;
      this.selector = selector;
    }
  };
  window.Router = Router;
})();
